#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

#define CAPACITY 1024
#define NUM_PRODUCERS 8
#define NUM_CONSUMERS 8
#define ITEMS_PER_PRODUCER 250000

typedef struct {
    atomic_size_t sequence;
    int data;
} cell_t;

typedef struct {
    cell_t buffer[CAPACITY];
    atomic_size_t head __attribute__((aligned(128)));
    atomic_size_t tail __attribute__((aligned(128)));
} ring_buffer_t;

void ring_init(ring_buffer_t *rb) {
    atomic_init(&rb->head, 0);
    atomic_init(&rb->tail, 0);
    for (size_t i = 0; i < CAPACITY; i++) {
        atomic_init(&rb->buffer[i].sequence, i);
    }
}

void ring_push(ring_buffer_t *rb, int value) {
    cell_t *cell;
    size_t pos = atomic_load_explicit(&rb->tail, memory_order_relaxed);
    for (;;) {
        cell = &rb->buffer[pos & (CAPACITY - 1)];
        size_t seq = atomic_load_explicit(&cell->sequence, memory_order_acquire);
        intptr_t dif = (intptr_t)seq - (intptr_t)pos;
        if (dif == 0) {
            if (atomic_compare_exchange_weak_explicit(&rb->tail, &pos, pos + 1, memory_order_relaxed, memory_order_relaxed)) {
                break;
            }
        } else if (dif < 0) {
            pos = atomic_load_explicit(&rb->tail, memory_order_relaxed);
        } else {
            pos = atomic_load_explicit(&rb->tail, memory_order_relaxed);
        }
    }
    cell->data = value;
    atomic_store_explicit(&cell->sequence, pos + 1, memory_order_release);
}

void ring_pop(ring_buffer_t *rb, int *value) {
    cell_t *cell;
    size_t pos = atomic_load_explicit(&rb->head, memory_order_relaxed);
    for (;;) {
        cell = &rb->buffer[pos & (CAPACITY - 1)];
        size_t seq = atomic_load_explicit(&cell->sequence, memory_order_acquire);
        intptr_t dif = (intptr_t)seq - (intptr_t)(pos + 1);
        if (dif == 0) {
            if (atomic_compare_exchange_weak_explicit(&rb->head, &pos, pos + 1, memory_order_relaxed, memory_order_relaxed)) {
                break;
            }
        } else if (dif < 0) {
            pos = atomic_load_explicit(&rb->head, memory_order_relaxed);
        } else {
            pos = atomic_load_explicit(&rb->head, memory_order_relaxed);
        }
    }
    *value = cell->data;
    atomic_store_explicit(&cell->sequence, pos + CAPACITY, memory_order_release);
}

ring_buffer_t rb;

void* producer(void *arg) {
    for (int i = 0; i < ITEMS_PER_PRODUCER; i++) {
        ring_push(&rb, i);
    }
    return NULL;
}

void* consumer(void *arg) {
    for (int i = 0; i < ITEMS_PER_PRODUCER; i++) {
        int val;
        ring_pop(&rb, &val);
    }
    return NULL;
}

int main() {
    ring_init(&rb);
    pthread_t prods[NUM_PRODUCERS], cons[NUM_CONSUMERS];

    for (int i = 0; i < NUM_PRODUCERS; i++) {
        pthread_create(&prods[i], NULL, producer, NULL);
    }
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        pthread_create(&cons[i], NULL, consumer, NULL);
    }

    for (int i = 0; i < NUM_PRODUCERS; i++) {
        pthread_join(prods[i], NULL);
    }
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        pthread_join(cons[i], NULL);
    }

    printf("FLAG: Ring Buffer TSAN Success!\n");
    return 0;
}
